/// Driver-chosen options for rendering DDL statements.
///
/// `Default` renders exactly the DDL Toasty emits without options. Drivers for
/// backends with stricter DDL rules (Aurora DSQL) set the fields they need.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct DdlOptions {
    /// Render `CREATE [UNIQUE] INDEX ASYNC`. The driver must then wait for the
    /// returned index-build job.
    pub async_index: bool,

    /// Render identity columns as `GENERATED BY DEFAULT AS IDENTITY (CACHE n)`.
    pub identity_cache: Option<u32>,
}
